('01a111ff-2c9d-7247-a70e-90533e7fdfb5', 'homepage_hero', 'Homepage Hero', 'Large hero banner at the top of the homepage.', 1440, 480, NULL, NULL, 512, '[\"jpg\", \"jpeg\", \"png\", \"webp\"]', 'desktop', 1, 0, 'upload', NULL, 50000, 1, 10, '2026-10-06 13:14:58', '2026-10-06 13:14:58'),
('01a111ff-2ca1-7101-af5f-8fd5069d4e38', 'homepage_secondary_left', 'Homepage Secondary – Left', 'Secondary banner slot on the left side of the homepage.', 600, 300, NULL, NULL, 256, '[\"jpg\", \"jpeg\", \"png\", \"webp\"]', 'all', 1, 0, 'upload', NULL, 25000, 1, 20, '2026-10-06 13:14:58', '2026-10-06 13:14:58'),
('01a111ff-2ca7-72b9-89ce-058736fa3a6b', 'homepage_secondary_right', 'Homepage Secondary – Right', 'Secondary banner slot on the right side of the homepage.', 600, 300, NULL, NULL, 256, '[\"jpg\", \"jpeg\", \"png\", \"webp\"]', 'all', 1, 0, 'upload', NULL, 25000, 1, 30, '2026-10-06 13:14:58', '2026-10-06 13:14:58'),
('01a111ff-2cad-71bf-ab2a-2936fdf6e6de', 'homepage_midpage', 'Homepage Mid-page', 'Wide mid-page banner on the homepage.', 1440, 300, NULL, NULL, 400, '[\"jpg\", \"jpeg\", \"png\", \"webp\"]', 'all', 2, 0, 'upload', NULL, 30000, 1, 40, '2026-10-06 13:14:58', '2026-10-06 13:14:58'),
('01a111ff-2cb3-718c-b822-c8a122a330ad', 'category_top', 'Category – Top Banner', 'Banner at the top of category listing pages.', 1200, 150, 375, 120, 256, '[\"jpg\", \"jpeg\", \"png\", \"webp\"]', 'all', 1, 1, 'upload', '[\"listing\", \"store\", \"brand\", \"category\"]', 20000, 1, 50, '2026-10-06 13:14:58', '2026-10-06 13:14:58'),
('01a111ff-2cb9-7320-83cb-77d4b50723b5', 'category_sidebar', 'Category – Sidebar', 'Sidebar banner on category pages (desktop only).', 300, 600, NULL, NULL, 256, '[\"jpg\", \"jpeg\", \"png\", \"webp\"]', 'desktop', 2, 0, 'upload', NULL, 15000, 1, 60, '2026-10-06 13:14:58', '2026-10-06 13:14:58'),
('01a111ff-2cbe-7187-8125-b296907d618b', 'search_top', 'Search Results – Top', 'Banner above search results.', 1200, 150, 375, 120, 256, '[\"jpg\", \"jpeg\", \"png\", \"webp\"]', 'all', 1, 1, 'upload', '[\"listing\", \"store\", \"brand\", \"category\"]', 20000, 1, 70, '2026-10-06 13:14:58', '2026-10-06 13:14:58'),
('01a111ff-2cc5-70c1-b1a1-22a9198948bf', 'cart_banner', 'Cart Page Banner', 'Promotional banner on the shopping cart page.', 900, 200, 375, 100, 200, '[\"jpg\", \"jpeg\", \"png\", \"webp\"]', 'all', 1, 1, 'upload', '[\"listing\", \"store\", \"brand\", \"category\"]', 18000, 1, 80, '2026-10-06 13:14:58', '2026-10-06 13:14:58'),
('01a111ff-2cca-7137-979b-d5841277aeb9', 'checkout_banner', 'Checkout Page Banner', 'Promotional banner on the checkout page.', 900, 200, NULL, NULL, 200, '[\"jpg\", \"jpeg\", \"png\", \"webp\"]', 'all', 1, 0, 'upload', NULL, 18000, 1, 90, '2026-10-06 13:14:58', '2026-10-06 13:14:58'),
('01a111ff-2ccf-7297-9261-e333ff81e3b5', 'product_page_bottom', 'Product Page – Bottom', 'Banner at the bottom of product detail pages.', 1200, 200, 375, 120, 256, '[\"jpg\", \"jpeg\", \"png\", \"webp\"]', 'all', 1, 1, 'product', '[\"listing\"]', 15000, 1, 100, '2026-10-06 13:14:58', '2026-10-06 13:14:58'),
('01a111ff-2cd5-72ed-8c1a-e097e7aafdb8', 'app_splash', 'App Splash Screen', 'Full-screen splash banner in the mobile app.', 375, 667, NULL, NULL, 300, '[\"jpg\", \"jpeg\", \"png\", \"webp\"]', 'app', 1, 0, 'upload', NULL, 35000, 1, 110, '2026-10-06 13:14:58', '2026-10-06 13:14:58'),
('01a111ff-2cdb-706e-9bfc-81f84bbabedd', 'app_home_top', 'App Home – Top Banner', 'Top banner on the mobile app home screen.', 375, 200, NULL, NULL, 200, '[\"jpg\", \"jpeg\", \"png\", \"webp\"]', 'app', 3, 0, 'upload', NULL, 28000, 1, 120, '2026-10-06 13:14:58', '2026-10-06 13:14:58'),
('01a111ff-2ce2-7188-ab99-124297fa91ad', 'email_header', 'Email Header Banner', 'Banner used in email campaign headers.', 600, 200, NULL, NULL, 150, '[\"jpg\", \"jpeg\", \"png\"]', 'all', 1, 0, 'upload', NULL, 12000, 1, 130, '2026-10-06 13:14:58', '2026-10-06 13:14:58');

