CREATE TABLE `blog_categories` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `parent_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Supports one level of sub-categories — a category with a parent cannot itself be a parent (enforce at app layer, not DB constraint, for simplicity)',
  `name_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_ar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `description_ar` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `cover_image_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `color_hex` varchar(7) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Brand accent color for this category, e.g. #3B82F6 — used for category pill/badge on the portal',
  `icon_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Heroicon or similar name for category badge',
  `seo_title_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_title_ar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_description_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `seo_description_ar` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `sort_order` int UNSIGNED NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `blog_categories`
--

INSERT INTO `blog_categories` (`id`, `parent_id`, `name_en`, `name_ar`, `slug`, `description_en`, `description_ar`, `cover_image_path`, `color_hex`, `icon_name`, `seo_title_en`, `seo_title_ar`, `seo_description_en`, `seo_description_ar`, `is_active`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES
('01a111ff-5ee1-72b2-aa78-cdffd5d627c8', NULL, 'Platform News', 'أخبار المنصة', 'platform-news', 'The latest updates, features, and announcements from our marketplace platform.', 'آخر التحديثات والميزات والإعلانات من منصة السوق لدينا.', NULL, '#3B82F6', 'megaphone', NULL, NULL, NULL, NULL, 1, 1, '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5ef9-727a-a56e-f6e764dc96df', NULL, 'Vendor Tips', 'نصائح البائعين', 'vendor-tips', 'Practical advice and best practices to help vendors grow their online business.', 'نصائح عملية وأفضل الممارسات لمساعدة البائعين على تنمية أعمالهم عبر الإنترنت.', NULL, '#10B981', 'light-bulb', NULL, NULL, NULL, NULL, 1, 2, '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5f19-721b-9e05-f343b78ddaf4', NULL, 'Seller Stories', 'قصص البائعين', 'seller-stories', 'Real success stories from vendors who have grown their business on our platform.', 'قصص نجاح حقيقية من بائعين نمّوا أعمالهم على منصتنا.', NULL, '#F59E0B', 'star', NULL, NULL, NULL, NULL, 1, 3, '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5f37-70e1-88f8-f875fa124808', NULL, 'E-Commerce Insights', 'رؤى التجارة الإلكترونية', 'ecommerce-insights', 'Trends, data, and analysis shaping the future of e-commerce in the region.', 'الاتجاهات والبيانات والتحليلات التي تشكّل مستقبل التجارة الإلكترونية في المنطقة.', NULL, '#8B5CF6', 'chart-bar', NULL, NULL, NULL, NULL, 1, 4, '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL);

