--
-- Table structure for table `blog_posts`
--

CREATE TABLE `blog_posts` (
  `id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `blog_category_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `country_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `author_admin_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `title_ar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'URL slug — shared across both languages, language is determined by the portal request locale',
  `excerpt_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Short summary shown on listing cards, max 300 chars',
  `excerpt_ar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `body_en` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Full article body — HTML from a rich text editor',
  `body_ar` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `featured_image_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Hero image shown at top of post and on listing cards',
  `featured_image_alt_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `featured_image_alt_ar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('draft','scheduled','published','archived') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `published_at` timestamp NULL DEFAULT NULL COMMENT 'When status became published — set automatically on first publish action, not manually editable',
  `scheduled_for` timestamp NULL DEFAULT NULL COMMENT 'When status=scheduled, auto-publishes at this datetime via a scheduled job',
  `archived_at` timestamp NULL DEFAULT NULL,
  `published_by_admin_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_title_en` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_title_ar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `seo_description_en` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `seo_description_ar` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `og_image_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Social share image — may differ from featured_image',
  `views_count` int UNSIGNED NOT NULL DEFAULT '0',
  `allow_comments` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Reserved for future use — blog launches without comments, toggle ready for when/if it is added',
  `is_featured` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Pinned/featured post shown in a hero slot on the blog index — only one featured post per country should be active at a time; enforce at app layer',
  `reading_time_minutes` int UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Computed from body word count at save time — ~200 words per minute average',
  `tags` json DEFAULT NULL COMMENT 'Free-form string tags, e.g. ["ecommerce","tips"]',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data for table `blog_posts`
--

INSERT INTO `blog_posts` (`id`, `blog_category_id`, `country_id`, `author_admin_id`, `title_en`, `title_ar`, `slug`, `excerpt_en`, `excerpt_ar`, `body_en`, `body_ar`, `featured_image_path`, `featured_image_alt_en`, `featured_image_alt_ar`, `status`, `published_at`, `scheduled_for`, `archived_at`, `published_by_admin_id`, `seo_title_en`, `seo_title_ar`, `seo_description_en`, `seo_description_ar`, `og_image_path`, `views_count`, `allow_comments`, `is_featured`, `reading_time_minutes`, `tags`, `created_at`, `updated_at`, `deleted_at`) VALUES
('01a111ff-5ee7-72cf-b05b-27d932fb6136', '01a111ff-5ee1-72b2-aa78-cdffd5d627c8', NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', 'Introducing Multi-Country Storefronts', 'نقدم لكم واجهات المتاجر متعددة البلدان', 'introducing-multi-country-storefronts', 'We\'ve expanded the platform to support storefronts for multiple countries, each with its own locale, currency, and catalog.', 'وسّعنا المنصة لدعم واجهات متاجر لدول متعددة، لكلٍّ منها لغتها وعملتها وكتالوجها الخاص.', '<p>We are thrilled to announce that our marketplace platform now supports fully independent storefronts for multiple countries. This means that vendors can tailor their product listings, pricing, and promotions to each market independently.</p><p>Each country storefront operates under its own domain, allowing customers to browse in their local language and pay in their local currency. This is a major step forward in our commitment to building a truly regional marketplace.</p><p>The rollout begins today across all partner portals. Existing vendors will find a new \"Country Settings\" section in their dashboard where they can configure country-specific visibility for their listings.</p><p>We will continue to roll out additional country-specific features — including localised shipping rates and tax rules — over the coming weeks. Stay tuned for more updates.</p>', '<p>يسعدنا الإعلان عن أن منصة السوق لدينا باتت تدعم الآن واجهات متاجر مستقلة كلياً لدول متعددة. يعني ذلك أن البائعين يمكنهم تخصيص قوائم منتجاتهم وأسعارهم وعروضهم الترويجية لكل سوق بشكل مستقل.</p><p>تعمل كل واجهة متجر لكل دولة تحت نطاقها الخاص، مما يتيح للعملاء التصفح بلغتهم المحلية والدفع بعملتهم المحلية. هذه خطوة مهمة إلى الأمام في التزامنا ببناء سوق إقليمي حقيقي.</p><p>يبدأ الطرح اليوم عبر جميع بوابات الشركاء. سيجد البائعون الحاليون قسمًا جديدًا باسم \"إعدادات الدولة\" في لوحة التحكم الخاصة بهم.</p>', NULL, NULL, NULL, 'published', '2026-10-05 13:15:11', NULL, NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', NULL, NULL, NULL, NULL, NULL, 196, 0, 0, 1, '[\"announcement\", \"storefronts\", \"multi-country\"]', '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5eed-71b2-a6c6-fced53d20feb', '01a111ff-5ee1-72b2-aa78-cdffd5d627c8', NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', 'New Vendor Dashboard Analytics — Know Your Numbers', 'تحليلات لوحة تحكم البائع الجديدة — اعرف أرقامك', 'new-vendor-dashboard-analytics', 'We\'ve launched a redesigned analytics section in the vendor dashboard with real-time sales charts, conversion funnels, and top-product reports.', 'أطلقنا قسم تحليلات مُعاد تصميمه في لوحة تحكم البائع يتضمن مخططات المبيعات الفورية وقمعات التحويل وتقارير أفضل المنتجات.', '<p>Data-driven selling starts with having the right data. That is why we rebuilt the analytics section of the vendor dashboard from the ground up.</p><p>The new analytics hub gives you a live view of your store performance: daily and weekly revenue charts, conversion rates from product views to purchases, your top-selling products by revenue and units, and a breakdown of traffic sources.</p><p>All charts update in near-real-time so you can react quickly to trending products or spot a sudden drop in conversions before it costs you. Filters let you drill down by date range, product category, or country.</p><p>This feature is available to all vendors on the platform starting today. Log in to your dashboard and navigate to Analytics to explore.</p>', '<p>يبدأ البيع المبني على البيانات بامتلاك البيانات الصحيحة. لهذا أعدنا بناء قسم التحليلات في لوحة تحكم البائع من الصفر.</p><p>يمنحك مركز التحليلات الجديد رؤية مباشرة لأداء متجرك: مخططات الإيرادات اليومية والأسبوعية، ومعدلات التحويل من مشاهدات المنتج إلى المشتريات، وأكثر منتجاتك مبيعًا حسب الإيرادات والوحدات، وتحليل مصادر الزيارات.</p><p>تتحدث جميع المخططات في الوقت الفعلي تقريبًا حتى تتمكن من الاستجابة بسرعة للمنتجات الرائجة.</p>', NULL, NULL, NULL, 'published', '2026-09-27 13:15:11', NULL, NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', NULL, NULL, NULL, NULL, NULL, 135, 0, 0, 1, '[\"analytics\", \"dashboard\", \"vendors\"]', '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5ef3-7257-8c3f-7efc15e74790', '01a111ff-5ee1-72b2-aa78-cdffd5d627c8', NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', 'Scheduled Maintenance — July 2026', 'صيانة مجدولة — يوليو 2026', 'platform-scheduled-maintenance-july', 'Our platform will undergo scheduled maintenance on 15 July 2026 from 02:00 to 04:00 GST. Orders placed during this window may be delayed.', 'ستخضع المنصة لصيانة مجدولة في 15 يوليو 2026 من الساعة 02:00 حتى 04:00 بتوقيت الخليج. قد تتأخر الطلبات المقدمة خلال هذه الفترة.', '<p>To ensure continued reliability and performance, we will be performing scheduled infrastructure maintenance on <strong>15 July 2026 from 02:00 to 04:00 GST</strong>.</p><p>During this window, the storefront and vendor dashboard will be in read-only mode. Customers will be able to browse but will not be able to place orders. Vendors will be able to view their dashboard but will not be able to update listings.</p><p>We have chosen this time window because it represents our lowest-traffic period. We expect the maintenance to be completed well within the two-hour window.</p><p>If you have any urgent orders to process, we recommend doing so before 01:30 GST on 15 July. We apologise for any inconvenience and thank you for your patience.</p>', '<p>لضمان الموثوقية والأداء المستمر، سنُجري صيانة بنية تحتية مجدولة في <strong>15 يوليو 2026 من الساعة 02:00 حتى 04:00 بتوقيت الخليج</strong>.</p><p>خلال هذه الفترة، ستكون واجهة المتجر ولوحة تحكم البائع في وضع القراءة فقط. يمكن للعملاء التصفح لكن لن يتمكنوا من تقديم طلبات.</p><p>نعتذر عن أي إزعاج ونشكركم على صبركم.</p>', NULL, NULL, NULL, 'published', '2026-09-17 13:15:11', NULL, NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', NULL, NULL, NULL, NULL, NULL, 178, 0, 0, 1, '[\"maintenance\", \"downtime\", \"announcement\"]', '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5f00-70c8-b105-b3f732eac896', '01a111ff-5ef9-727a-a56e-f6e764dc96df', NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', 'How to Write Product Titles That Actually Convert', 'كيف تكتب عناوين منتجات تحقق تحويلات فعلية', 'how-to-write-product-titles-that-convert', 'Your product title is the first thing a shopper reads. Here\'s how to write titles that are clear, keyword-rich, and designed to drive clicks.', 'عنوان منتجك هو أول ما يقرأه المتسوق. إليك كيفية كتابة عناوين واضحة وغنية بالكلمات المفتاحية ومصممة لزيادة النقرات.', '<p>On a marketplace with thousands of products, your title is your first — and sometimes only — chance to get a shopper\'s attention. A poorly written title means your listing gets skipped; a well-crafted one can double your click-through rate.</p><h2>Lead with the most important keyword</h2><p>Shoppers search for specific things. Make sure the primary keyword for your product appears within the first 5 words of your title. For example, \"Wireless Bluetooth Headphones with Noise Cancelling — 30h Battery\" is far stronger than \"High Quality Sound Product by BrandX\".</p><h2>Include the key spec</h2><p>After the keyword, add the most decision-driving specification: size, colour, material, capacity, or compatibility. This helps the shopper qualify your product before clicking.</p><h2>Keep it under 80 characters</h2><p>Titles longer than 80 characters are often truncated on mobile. Put your most important information first.</p><h2>Avoid keyword stuffing</h2><p>Repeating the same keyword multiple times hurts readability and does not improve search ranking on our platform. Write for the shopper first.</p>', '<p>في سوق يضم آلاف المنتجات، يمثّل عنوانك فرصتك الأولى — وأحياناً الوحيدة — لجذب انتباه المتسوق. العنوان المكتوب بشكل سيئ يعني تخطّي قائمتك؛ أما العنوان المصاغ جيداً فيمكنه مضاعفة معدل النقر.</p><h2>ابدأ بالكلمة المفتاحية الأهم</h2><p>يبحث المتسوقون عن أشياء محددة. تأكد من ظهور الكلمة المفتاحية الأساسية لمنتجك ضمن أول 5 كلمات من عنوانك.</p><h2>اذكر المواصفة الأساسية</h2><p>بعد الكلمة المفتاحية، أضف المواصفة الأكثر تأثيراً في قرار الشراء: الحجم، اللون، المادة، السعة، أو التوافق.</p><h2>حافظ على العنوان تحت 80 حرفاً</h2><p>العناوين الأطول من 80 حرفاً غالباً ما تُقطع على الجوال. ضع أهم المعلومات أولاً.</p>', NULL, NULL, NULL, 'published', '2026-09-15 13:15:11', NULL, NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', NULL, NULL, NULL, NULL, NULL, 495, 0, 0, 1, '[\"listings\", \"copywriting\", \"conversion\"]', '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5f06-70db-b814-07fda6d90b9e', '01a111ff-5ef9-727a-a56e-f6e764dc96df', NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', '5 Pricing Strategies Every Marketplace Vendor Should Know', '5 استراتيجيات تسعير يجب أن يعرفها كل بائع في السوق', 'pricing-strategies-for-marketplace-vendors', 'Pricing is not just about being the cheapest. Discover five strategies — from anchor pricing to bundle pricing — that improve margins and win more sales.', 'التسعير لا يعني فقط أن تكون الأرخص. اكتشف خمس استراتيجيات — من التسعير المرجعي إلى تسعير الحزم — التي تحسّن الهوامش وتربح المزيد من المبيعات.', '<p>Price is the single most-scrutinised element of any product listing. Yet many vendors set prices reactively — either matching the lowest competitor or guessing what feels right. Here are five deliberate strategies.</p><h2>1. Anchor Pricing</h2><p>Show the original price alongside the sale price. The \"was/now\" contrast makes the sale price feel like a great deal even if it has always been that price.</p><h2>2. Bundle Pricing</h2><p>Group related products together at a discount. Bundles increase average order value and make it harder for competitors to price-match directly.</p><h2>3. Charm Pricing</h2><p>Prices ending in 9 or 99 (e.g., 49.99 instead of 50.00) are processed by shoppers as significantly lower, even though the difference is negligible.</p><h2>4. Value-Based Pricing</h2><p>Price based on what your product is worth to the customer, not just your cost plus margin. Premium materials, unique design, or a strong brand can justify a price above the market average.</p><h2>5. Loss Leader Pricing</h2><p>Price one high-traffic product at or near cost to drive shoppers to your store, then rely on related-product purchases for margin.</p>', '<p>السعر هو العنصر الأكثر فحصاً في أي قائمة منتج. ومع ذلك، يحدد كثير من البائعين الأسعار بشكل تفاعلي. إليك خمس استراتيجيات متعمدة.</p><h2>1. التسعير المرجعي</h2><p>اعرض السعر الأصلي إلى جانب سعر البيع. يجعل التباين \"كان/الآن\" سعر البيع يبدو صفقة رائعة.</p><h2>2. تسعير الحزم</h2><p>اجمع المنتجات ذات الصلة بخصم. تزيد الحزم من متوسط قيمة الطلب.</p><h2>3. التسعير بالأرقام السحرية</h2><p>الأسعار المنتهية بـ 9 أو 99 يعالجها المتسوقون كأسعار أقل بكثير.</p><h2>4. التسعير القائم على القيمة</h2><p>سعّر بناءً على ما يستحقه منتجك للعميل وليس فقط تكلفتك مضافاً إليها هامش الربح.</p><h2>5. التسعير القائد بالخسارة</h2><p>سعّر منتجاً ذا حركة مرور عالية بالتكلفة أو قريبة منها لجذب المتسوقين إلى متجرك.</p>', NULL, NULL, NULL, 'published', '2026-09-27 13:15:11', NULL, NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', NULL, NULL, NULL, NULL, NULL, 198, 0, 0, 1, '[\"pricing\", \"strategy\", \"sales\"]', '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5f0f-7153-ac20-83681026112e', '01a111ff-5ef9-727a-a56e-f6e764dc96df', NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', 'Optimising Product Images for Higher Conversions', 'تحسين صور المنتج لتحقيق تحويلات أعلى', 'optimising-product-images-for-conversions', 'Blurry or poorly lit product images are costing you sales. Learn the six image rules top-performing vendors follow on our platform.', 'الصور الضبابية أو السيئة الإضاءة تُكلّفك مبيعات. تعرّف على القواعد الست للصور التي يتبعها أفضل البائعين أداءً على منصتنا.', '<p>Online shoppers cannot touch, smell, or try on your product. Your images are their only physical reference. This is why product photography has a direct impact on conversion rate.</p><h2>Rule 1: Use a white or neutral background for the hero shot</h2><p>A clean background removes distractions and makes the product the star. It also ensures your listing looks consistent alongside other listings on search results pages.</p><h2>Rule 2: Shoot at least 5 angles</h2><p>Front, back, side, close-up detail, and in-use or lifestyle shot. Shoppers who see more angles buy with more confidence and return less often.</p><h2>Rule 3: Minimum 1000×1000 pixels</h2><p>Our platform supports zoom on hover. Images below 1000px look blurry when zoomed. Use at least 1500×1500 for best results.</p><h2>Rule 4: Show scale</h2><p>If size matters for your product — and it usually does — include an image with a size reference (a hand, a common object, a ruler).</p><h2>Rule 5: Avoid text overlays on the hero image</h2><p>Text on product images looks like promotional banners and erodes trust. Put specs in the title and bullet points instead.</p><h2>Rule 6: Use consistent lighting</h2><p>Inconsistent lighting across your image set makes your store look unprofessional. Natural diffused light or a lightbox gives you the most reliable results.</p>', '<p>لا يستطيع المتسوقون عبر الإنترنت لمس منتجك أو شمّه أو تجربته. صورك هي مرجعهم المادي الوحيد.</p><h2>القاعدة 1: استخدم خلفية بيضاء أو محايدة للصورة الرئيسية</h2><p>الخلفية النظيفة تزيل المشتتات وتجعل المنتج هو النجم.</p><h2>القاعدة 2: التقط صوراً من 5 زوايا على الأقل</h2><p>أمام، خلف، جانب، تفصيل مقرّب، وصورة استخدام أو نمط حياة.</p><h2>القاعدة 3: الحد الأدنى 1000×1000 بكسل</h2><p>منصتنا تدعم التكبير عند التحويم. الصور أقل من 1000 بكسل تبدو ضبابية عند التكبير.</p><h2>القاعدة 4: أظهر الحجم</h2><p>إذا كان الحجم مهماً لمنتجك، أدرج صورة مع مرجع للحجم.</p><h2>القاعدة 5: تجنب تراكبات النص على الصورة الرئيسية</h2><p>النص على صور المنتج يبدو كلافتات ترويجية ويضعف الثقة.</p><h2>القاعدة 6: استخدم إضاءة متسقة</h2><p>الإضاءة غير المتسقة عبر مجموعة صورك تجعل متجرك يبدو غير احترافي.</p>', NULL, NULL, NULL, 'published', '2026-09-09 13:15:11', NULL, NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', NULL, NULL, NULL, NULL, NULL, 365, 0, 0, 1, '[\"photography\", \"listings\", \"conversion\"]', '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5f20-72e4-8b71-fe3a713211d9', '01a111ff-5f19-721b-9e05-f343b78ddaf4', NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', 'How Amira Grew Her Abaya Brand 300% in One Year', 'كيف نمّت أميرة علامتها التجارية للعبايات بنسبة 300% في عام واحد', 'how-amira-grew-her-abaya-brand-300-percent', 'Amira Al-Rashidi started selling modest fashion from her living room. A year later she is one of the platform\'s top-10 fashion vendors. Here is her story.', 'بدأت أميرة الراشدي بيع الأزياء المحتشمة من غرفة معيشتها. بعد عام أصبحت من أفضل 10 بائعين في قطاع الأزياء على المنصة. هذه قصتها.', '<p>Amira Al-Rashidi had been designing abayas for friends and family for years before she decided to take her passion online. \"I was terrified,\" she admits. \"I had no e-commerce experience, no big budget for photography, just a phone camera and a lot of hope.\"</p><p>She joined the platform in June 2024 with five designs and a determination to treat every customer review as a free consultant. Within three months she had earned her first 50 five-star reviews and was reinvesting every dirham of profit into better fabric and a proper photo setup.</p><p>The turning point came when she ran her first flash sale. \"I cut 20% off my best-seller for 48 hours and the notifications didn\'t stop,\" she says. \"I sold in two days what used to take two weeks.\"</p><p>Today, Amira employs three seamstresses, ships to six countries, and is preparing to launch a kids\' line. Her advice to new vendors: \"Reply to every message within an hour. Speed builds trust faster than any marketing budget.\"</p>', '<p>كانت أميرة الراشدي تصمم العبايات لأصدقائها وعائلتها لسنوات قبل أن تقرر أخذ شغفها إلى الإنترنت. \"كنت خائفة جداً،\" تعترف. \"لم يكن لديّ خبرة في التجارة الإلكترونية، ولا ميزانية كبيرة للتصوير، فقط كاميرا هاتف وكثير من الأمل.\"</p><p>انضمت إلى المنصة في يونيو 2024 بخمسة تصميمات وتصميم على معاملة كل تقييم من العملاء كمستشار مجاني. في غضون ثلاثة أشهر حصلت على أول 50 تقييم خمس نجوم.</p><p>جاءت نقطة التحول عندما أجرت أول تخفيض سريع لها. \"خفّضت 20% على أكثر منتجاتي مبيعاً لمدة 48 ساعة ولم تتوقف الإشعارات،\" تقول. \"بعت في يومين ما كان يستغرق أسبوعين.\"</p><p>اليوم توظّف أميرة ثلاث خياطات وتشحن إلى ست دول. نصيحتها للبائعين الجدد: \"ردّ على كل رسالة خلال ساعة. السرعة تبني الثقة أسرع من أي ميزانية تسويقية.\"</p>', NULL, NULL, NULL, 'published', '2026-09-23 13:15:11', NULL, NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', NULL, NULL, NULL, NULL, NULL, 146, 0, 0, 1, '[\"success-story\", \"fashion\", \"growth\"]', '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5f27-7135-8a92-9eb36c9dd2e0', '01a111ff-5f19-721b-9e05-f343b78ddaf4', NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', 'From Garage to Fulfilment Centre: Karim\'s Electronics Journey', 'من الجراج إلى مركز التوصيل: رحلة كريم في الإلكترونيات', 'from-garage-to-fulfillment-center-karim-story', 'Karim started selling refurbished phones from his garage. Three years on, he runs a dedicated fulfilment warehouse and ships 200+ orders a day.', 'بدأ كريم بيع الهواتف المُجدَّدة من جراجه. بعد ثلاث سنوات يدير مستودع توصيل مخصصاً ويشحن أكثر من 200 طلب يومياً.', '<p>In 2022, Karim Hassan was a telecom technician with a side hustle: buying damaged smartphones, repairing them, and reselling on local classifieds. The margins were good but the audience was tiny. A colleague suggested trying an online marketplace.</p><p>\"My first listing got two views in the first week,\" he laughs. \"I nearly gave up.\" He didn\'t. Instead he studied how the platform search algorithm worked, optimised his titles, and shot proper product photos against a white sheet pinned to his garage wall.</p><p>By month three, he was shipping 15 orders a day. By month twelve, 80. Today, Karim\'s warehouse processes over 200 orders daily, carries a 4.9-star rating across 8,000+ reviews, and operates a small repair team that turns around refurbished units in 24 hours.</p><p>\"The platform gave me the reach,\" he says. \"But it was the reviews that gave me the credibility. I obsessed over every single one.\"</p>', '<p>في عام 2022، كان كريم حسان فنياً في مجال الاتصالات مع عمل جانبي: شراء الهواتف الذكية التالفة وإصلاحها وإعادة بيعها في الإعلانات المحلية.</p><p>\"حصل إعلاني الأول على مشاهدتين في الأسبوع الأول،\" يضحك. \"كدت أستسلم.\" لكنه لم يفعل. بدلاً من ذلك درس كيف يعمل خوارزمية بحث المنصة وحسّن عناوينه والتقط صوراً احترافية.</p><p>بحلول الشهر الثالث كان يشحن 15 طلباً يومياً. اليوم يعالج مستودع كريم أكثر من 200 طلب يومياً ويحمل تقييم 4.9 نجوم عبر أكثر من 8000 تقييم.</p><p>\"المنصة أعطتني الوصول،\" يقول. \"لكن التقييمات هي التي أعطتني المصداقية.\"</p>', NULL, NULL, NULL, 'published', '2026-09-13 13:15:11', NULL, NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', NULL, NULL, NULL, NULL, NULL, 479, 0, 0, 1, '[\"success-story\", \"electronics\", \"growth\"]', '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5f30-72ae-ab3c-c5f91806140e', '01a111ff-5f19-721b-9e05-f343b78ddaf4', NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', 'Building a Food Brand from a Home Kitchen', 'بناء علامة تجارية غذائية من مطبخ منزلي', 'building-a-food-brand-from-a-home-kitchen', 'Nour turned her grandmother\'s za\'atar recipe into a thriving packaged food business without ever leaving her kitchen. Here\'s how she did it.', 'حوّلت نور وصفة جدتها للزعتر إلى أعمال تجارية مزدهرة في مجال الأغذية المعبأة دون أن تغادر مطبخها. إليك كيف فعلت ذلك.', '<p>Nour Khalil had a secret weapon: her grandmother\'s za\'atar blend, a recipe passed down three generations and never shared outside the family. When friends kept asking where to buy it, Nour saw an opportunity.</p><p>She spent three months getting her home kitchen certified for food production, designed a simple label on her laptop, and listed her first product — a 200g jar of hand-mixed za\'atar — on the platform in early 2025.</p><p>The first order came within hours. \"I cried,\" she says. \"Someone I didn\'t know was willing to pay for something I made.\"</p><p>Word spread quickly. Customers started tagging her on social media. She added two more SKUs: a chilli-laced version and a za\'atar-olive oil dipping blend. By the end of 2025, she was selling 1,200 jars a month and had moved to a small licensed production space.</p><p>Her biggest lesson: \"Packaging matters as much as the product. I invested in proper jars and a professionally printed label early on, and I think that\'s what made people trust a brand they\'d never heard of.\"</p>', '<p>كان لدى نور خليل سلاح سري: مزيج الزعتر الخاص بجدتها، وصفة توارثتها ثلاثة أجيال ولم تُشارَك قط خارج العائلة.</p><p>أمضت ثلاثة أشهر في الحصول على شهادة مطبخها المنزلي لإنتاج الغذاء، وصمّمت علامة بسيطة على حاسوبها، وأدرجت منتجها الأول على المنصة في مطلع 2025.</p><p>جاء الطلب الأول في غضون ساعات. \"بكيت،\" تقول. \"كان هناك شخص لا أعرفه على استعداد للدفع مقابل شيء صنعته.\"</p><p>بحلول نهاية 2025 كانت تبيع 1200 جرة شهرياً. درسها الأكبر: \"التغليف بنفس أهمية المنتج. استثمرت في جرات مناسبة وعلامة مطبوعة احترافياً مبكراً، وأعتقد أن ذلك هو ما جعل الناس يثقون بعلامة تجارية لم يسمعوا بها قط.\"</p>', NULL, NULL, NULL, 'published', '2026-09-22 13:15:11', NULL, NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', NULL, NULL, NULL, NULL, NULL, 354, 0, 0, 1, '[\"success-story\", \"food\", \"home-business\"]', '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5f3d-70fe-8d2c-cf6e9d16e401', '01a111ff-5f37-70e1-88f8-f875fa124808', NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', 'Mobile Commerce Trends in the Gulf — What the Data Says for 2026', 'اتجاهات التجارة عبر الجوال في الخليج — ما تقوله البيانات لعام 2026', 'mobile-commerce-trends-gulf-2026', 'Over 78% of orders on our platform are now placed from mobile devices. We break down the numbers and what they mean for how you sell.', 'أكثر من 78% من الطلبات على منصتنا تُقدَّم الآن من الأجهزة المحمولة. نحلّل الأرقام وما تعنيه لطريقة بيعك.', '<p>Mobile commerce is not the future of retail in the Gulf — it is the present. Platform data for H1 2026 shows that 78.4% of all orders were placed on a smartphone or tablet, up from 71% in the same period last year.</p><h2>Peak shopping hours are late evening</h2><p>The busiest shopping period is 21:00–23:00 local time across all countries on the platform. Vendors who schedule flash sales or push notifications in this window consistently see 30–40% higher engagement than those who broadcast during business hours.</p><h2>Session length is shortening</h2><p>Average mobile session length dropped from 6.2 minutes to 4.8 minutes year-on-year. Shoppers are making faster decisions. This means your first product image and title need to do more work in less time — there is no room for ambiguity.</p><h2>Cart abandonment is highest on Friday afternoon</h2><p>Friday afternoon sees the highest cart abandonment rate (67%) of any time slot. Automated cart-recovery messages sent within 2 hours of abandonment recover 18% of those carts on average.</p><h2>What this means for your store</h2><p>Optimise your listing images for small screens. Keep titles concise. Set up cart-recovery automations. And consider timing your best promotions for the 21:00–23:00 window.</p>', '<p>التجارة عبر الجوال ليست مستقبل التجزئة في الخليج — إنها الحاضر. تُظهر بيانات المنصة للنصف الأول من 2026 أن 78.4% من جميع الطلبات قُدِّمت من هاتف ذكي أو جهاز لوحي.</p><h2>ذروة ساعات التسوق في المساء المتأخر</h2><p>أكثر فترات التسوق ازدحاماً هي 21:00-23:00 بالتوقيت المحلي. البائعون الذين يجدولون التخفيضات السريعة في هذه الفترة يرون باستمرار تفاعلاً أعلى بنسبة 30-40%.</p><h2>مدة الجلسة تتقلص</h2><p>انخفض متوسط مدة جلسة الجوال من 6.2 دقيقة إلى 4.8 دقيقة على أساس سنوي. المتسوقون يتخذون قرارات أسرع.</p><h2>التخلي عن سلة التسوق أعلى مساء الجمعة</h2><p>يشهد مساء الجمعة أعلى معدل تخلي عن سلة التسوق (67%). رسائل استرداد السلة المُرسلة خلال ساعتين تسترد 18% من تلك السلال في المتوسط.</p>', NULL, NULL, NULL, 'published', '2026-09-09 13:15:11', NULL, NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', NULL, NULL, NULL, NULL, NULL, 393, 0, 0, 1, '[\"mobile\", \"data\", \"trends\", \"gulf\"]', '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5f42-7290-9b93-1f71ec1ce98f', '01a111ff-5f37-70e1-88f8-f875fa124808', NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', 'The Ramadan Commerce Playbook for 2026', 'دليل التجارة في رمضان لعام 2026', 'ramadan-commerce-playbook-2026', 'Ramadan is the biggest e-commerce event of the year in the region. Here\'s how to prepare your store, plan your promotions, and protect your margins.', 'رمضان هو أكبر حدث للتجارة الإلكترونية في المنطقة خلال العام. إليك كيفية تجهيز متجرك وتخطيط عروضك وحماية هوامشك.', '<p>Ramadan consistently drives the highest order volumes of the year on our platform — in 2025, Ramadan month accounted for 22% of the full year\'s GMV. For 2026, the window runs from approximately 1 March to 30 March. Here is how to make the most of it.</p><h2>Stock up 4 weeks early</h2><p>Supply chains tighten in the weeks leading up to Ramadan. Place your restocking orders by early February to avoid stockouts during peak demand.</p><h2>Adjust your listing copy</h2><p>Shoppers in Ramadan are often buying gifts, food, and home items for entertaining. Reframe your product descriptions around the occasion where relevant: \"Perfect Ramadan gift\", \"Ideal for Iftar gatherings\".</p><h2>Plan your promotions calendar</h2><p>The most effective Ramadan promotions run during: the first week (novelty excitement), mid-Ramadan (the \"lull\" that benefits from a boost), and the last 10 days (intense buying for Eid).</p><h2>Protect your margins</h2><p>Every vendor discounts during Ramadan. Instead of matching every competitor, pick two or three products for deep discounts and keep the rest at your normal price with a compelling Ramadan narrative.</p><h2>Prepare your customer service</h2><p>Order volume spikes mean enquiry volume spikes. Pre-write responses to your 10 most common questions and make sure someone is monitoring messages during evening Iftar hours.</p>', '<p>يُحقق رمضان باستمرار أعلى أحجام طلبات في العام على منصتنا — في 2025 شكّل شهر رمضان 22% من إجمالي حجم المعاملات السنوي.</p><h2>احتياطياتك قبل 4 أسابيع</h2><p>تتشدد سلاسل التوريد في الأسابيع التي تسبق رمضان. ضع طلبات إعادة التخزين بحلول مطلع فبراير لتجنب نفاد المخزون خلال ذروة الطلب.</p><h2>اضبط نص قوائمك</h2><p>غالباً ما يشتري المتسوقون في رمضان هدايا ومواد غذائية وأغراض منزلية. أعد صياغة أوصاف منتجاتك حول المناسبة: \"هدية رمضان المثالية\"، \"مثالي لتجمعات الإفطار\".</p><h2>خطط تقويم عروضك</h2><p>أكثر العروض الترويجية فعالية تعمل خلال: الأسبوع الأول، ومنتصف رمضان، والعشر الأواخر (شراء مكثف لعيد الفطر).</p><h2>احمِ هوامشك</h2><p>كل بائع يخفّض في رمضان. بدلاً من مجاراة كل منافس، اختر منتجين أو ثلاثة لخصومات كبيرة وأبقِ الباقي بسعرك العادي.</p>', NULL, NULL, NULL, 'published', '2026-09-10 13:15:11', NULL, NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', NULL, NULL, NULL, NULL, NULL, 185, 0, 0, 1, '[\"ramadan\", \"seasonal\", \"promotions\", \"strategy\"]', '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL),
('01a111ff-5f49-735a-b32c-b293a18ed4fb', '01a111ff-5f37-70e1-88f8-f875fa124808', NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', 'The Rise of Social Commerce in the Region', 'صعود التجارة الاجتماعية في المنطقة', 'the-rise-of-social-commerce-in-the-region', 'Social media is no longer just a marketing channel — it is becoming a direct sales channel. Here\'s what the shift means for marketplace vendors.', 'لم تعد وسائل التواصل الاجتماعي مجرد قناة تسويق — إنها تتحول إلى قناة مبيعات مباشرة. إليك ما يعنيه هذا التحول لبائعي السوق.', '<p>Social commerce — the practice of buying directly through social media platforms — is growing faster in the MENA region than anywhere else in the world. A 2025 report by a leading regional research firm found that 41% of Gulf internet users had completed a purchase through a social platform in the previous 12 months, up from 28% in 2023.</p><h2>What is driving the growth?</h2><p>Three factors are converging: the Gulf\'s extremely high social media penetration (over 90% in the UAE and KSA), the cultural preference for recommendation-based discovery, and the maturation of in-app payment infrastructure.</p><h2>How does this affect marketplace vendors?</h2><p>Social commerce and marketplace commerce are not mutually exclusive — in fact, the most successful vendors use social channels to drive discovery and their marketplace store to handle fulfilment, reviews, and trust.</p><p>The practical implication: invest in short-form video content that showcases your products, link directly to your marketplace listings, and monitor which social platforms drive your highest-converting traffic using your dashboard analytics.</p><h2>The outlook for 2026–2027</h2><p>We expect in-app shopping features to expand further across the region\'s major social platforms. Vendors who build a social audience now will have a significant advantage when those features mature.</p>', '<p>التجارة الاجتماعية — ممارسة الشراء مباشرة عبر منصات التواصل الاجتماعي — تنمو في منطقة الشرق الأوسط وشمال أفريقيا بشكل أسرع من أي مكان آخر في العالم.</p><h2>ما الذي يقود النمو؟</h2><p>ثلاثة عوامل تتقاطع: انتشار وسائل التواصل الاجتماعي المرتفع جداً في الخليج، والتفضيل الثقافي للاكتشاف القائم على التوصيات، ونضج البنية التحتية للدفع داخل التطبيقات.</p><h2>كيف يؤثر هذا على بائعي السوق؟</h2><p>التجارة الاجتماعية وتجارة السوق ليستا متعارضتين — في الواقع، يستخدم أنجح البائعين القنوات الاجتماعية للاكتشاف ومتجرهم في السوق للتعامل مع التوصيل والتقييمات والثقة.</p><h2>التوقعات لـ 2026-2027</h2><p>نتوقع أن تتوسع ميزات التسوق داخل التطبيقات عبر منصات التواصل الاجتماعي الكبرى في المنطقة. البائعون الذين يبنون جمهوراً اجتماعياً الآن سيتمتعون بميزة كبيرة عندما تنضج تلك الميزات.</p>', NULL, NULL, NULL, 'published', '2026-09-06 13:15:11', NULL, NULL, '150a1d19-b353-4bb1-b317-f943fde166a4', NULL, NULL, NULL, NULL, NULL, 375, 0, 0, 1, '[\"social-commerce\", \"trends\", \"strategy\"]', '2026-10-06 13:15:11', '2026-10-06 13:15:11', NULL);

