INSERT INTO `classified_contract_templates` (`id`, `classified_category_id`, `category_scope`, `product_category_id`, `name`, `version`, `content_en`, `content_ar`, `is_active`, `created_by_admin_id`, `created_at`, `updated_at`, `is_published`, `variables_schema`) VALUES
('01a111ff-3812-7040-afc3-4464e27a9d6b', NULL, 'classified', NULL, 'Classified Vendor Agreement', 1, 'CLASSIFIED VENDOR AGREEMENT\n\nThis agreement is made between {{platform.name_en}} and {{vendor.store_name}} ({{vendor.business_name}}), registration {{vendor.registration_number}}, tax ID {{vendor.tax_id}}, located at {{vendor.address}}, {{vendor.country}}.\n\n1. The vendor will publish only accurate listings in the category {{category.name_en}}.\n2. Listings must comply with platform policies and applicable law.\n3. The platform may reject, pause or remove any listing that breaches this agreement.\n4. This agreement version {{contract.version}} takes effect on {{contract.date}}.\n\nSigned by: {{vendor.signer_name}}', 'اتفاقية البائع للإعلانات المبوّبة\n\nتُبرم هذه الاتفاقية بين {{platform.name_ar}} و{{vendor.store_name}} ({{vendor.business_name}})، رقم السجل {{vendor.registration_number}}، الرقم الضريبي {{vendor.tax_id}}، والعنوان {{vendor.address}}، {{vendor.country}}.\n\n1. يلتزم البائع بنشر إعلانات دقيقة فقط في فئة {{category.name_ar}}.\n2. يجب أن تتوافق الإعلانات مع سياسات المنصة والأنظمة المعمول بها.\n3. يحق للمنصة رفض أي إعلان أو إيقافه أو إزالته في حال مخالفة هذه الاتفاقية.\n4. تسري هذه النسخة {{contract.version}} اعتباراً من {{contract.date}}.\n\nوقّعها: {{vendor.signer_name}}', 1, '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-10-06 13:15:01', '2026-10-06 13:15:01', 1, '[\"vendor.store_name\", \"vendor.business_name\", \"vendor.business_type\", \"vendor.registration_number\", \"vendor.tax_id\", \"vendor.contact_email\", \"vendor.contact_phone\", \"vendor.address\", \"vendor.country\", \"vendor.signer_name\", \"platform.name_en\", \"platform.name_ar\", \"category.name_en\", \"category.name_ar\", \"contract.version\", \"contract.date\"]'),
('01a111ff-3818-721f-85ca-0e332eb59959', NULL, 'product', NULL, 'Product Vendor Agreement', 1, 'PRODUCT VENDOR AGREEMENT\n\nThis agreement is made between {{platform.name_en}} and {{vendor.store_name}} ({{vendor.business_name}}), registration {{vendor.registration_number}}, tax ID {{vendor.tax_id}}, located at {{vendor.address}}, {{vendor.country}}.\n\n1. The vendor will sell only genuine products in the category {{category.name_en}}.\n2. The vendor is responsible for product quality, pricing accuracy and stock levels.\n3. The platform may suspend any product listing that breaches this agreement.\n4. This agreement version {{contract.version}} takes effect on {{contract.date}}.\n\nSigned by: {{vendor.signer_name}}', 'اتفاقية البائع للمنتجات\n\nتُبرم هذه الاتفاقية بين {{platform.name_ar}} و{{vendor.store_name}} ({{vendor.business_name}})، رقم السجل {{vendor.registration_number}}، الرقم الضريبي {{vendor.tax_id}}، والعنوان {{vendor.address}}، {{vendor.country}}.\n\n1. يلتزم البائع ببيع منتجات أصلية فقط في فئة {{category.name_ar}}.\n2. البائع مسؤول عن جودة المنتجات ودقة الأسعار ومستويات المخزون.\n3. يحق للمنصة إيقاف أي منتج يخالف هذه الاتفاقية.\n4. تسري هذه النسخة {{contract.version}} اعتباراً من {{contract.date}}.\n\nوقّعها: {{vendor.signer_name}}', 1, '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-10-06 13:15:01', '2026-10-06 13:15:01', 1, '[\"vendor.store_name\", \"vendor.business_name\", \"vendor.business_type\", \"vendor.registration_number\", \"vendor.tax_id\", \"vendor.contact_email\", \"vendor.contact_phone\", \"vendor.address\", \"vendor.country\", \"vendor.signer_name\", \"platform.name_en\", \"platform.name_ar\", \"category.name_en\", \"category.name_ar\", \"contract.version\", \"contract.date\"]');

