  `gateway_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `event_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `payload` json NOT NULL,
  `headers` json DEFAULT NULL,
  `signature_valid` tinyint DEFAULT NULL,
  `processed` tinyint NOT NULL DEFAULT '0',
  `processing_error` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `payment_transaction_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

