('01a111ff-61e2-701e-9736-015d49fb35c3', 'faq', 'contact_cta', 'button', 'link', 'Contact Support', 'تواصل مع الدعم', 'mailto:sellers@noon.com', 102, 1, NULL, '2026-10-06 13:15:11', '2026-10-06 13:15:11'),
('01a111ff-61e8-72e0-906b-89a84123c65f', 'sellers', 'hero', 'eyebrow', 'text', 'Sellers', 'البائعين', NULL, 1, 1, NULL, '2026-10-06 13:15:11', '2026-10-06 13:15:11'),
('01a111ff-61ee-73b1-a774-2b2a013be704', 'sellers', 'hero', 'subtitle', 'text', 'Join thousands of sellers leveraging our ad solutions to reach their marketing and sales objectives across locations and irrespective of their budgets.', 'انضم إلى آلاف البائعين الذين يستفيدون من حلولنا الإعلانية لتحقيق أهدافهم التسويقية والمبيعاتية عبر المواقع بغض النظر عن ميزانياتهم.', NULL, 2, 1, NULL, '2026-10-06 13:15:11', '2026-10-06 13:15:11'),
('01a111ff-61f4-7219-bae1-4b5b85c73530', 'sellers', 'hero', 'cta_button', 'link', 'Start now', 'ابدأ الآن', '/register', 3, 1, NULL, '2026-10-06 13:15:11', '2026-10-06 13:15:11'),
