INSERT INTO `products` (`id`, `category_id`, `brand_id`, `name_en`, `name_ar`, `slug`, `model_number`, `gtin`, `description_en`, `description_ar`, `short_desc_en`, `short_desc_ar`, `status`, `has_custom_attributes`, `is_hidden`, `is_featured`, `requires_brand_auth`, `is_age_restricted`, `min_age`, `is_hazardous`, `has_variants`, `seller_count`, `total_sold`, `view_count`, `ai_quality_score`, `seo_title_en`, `seo_title_ar`, `seo_description_en`, `seo_description_ar`, `published_at`, `created_by_admin_id`, `created_at`, `updated_at`, `deleted_at`, `size_guide_image`, `qr_code_path`) VALUES
('0a5543a4-449e-4e7e-984e-cf54067d1d82', '571611f2-cd5c-4a9b-b7d9-8bc1cafa2f71', 'bcac4ce3-9113-447d-ad37-32e4cc017a9d', 'Bosch S5 Car Battery 74Ah', 'بطارية سيارة بوش S5 74 أمبير', 'bosch-s5-car-battery-74ah', NULL, NULL, '<p>The Bosch S5 battery offers superior starting power and excellent cycling stability. Ideal for modern vehicles with multiple electronic systems.</p>', '<p>تقدم بطارية بوش S5 قدرة بدء تشغيل فائقة واستقرار دوري ممتاز. مثالية للمركبات الحديثة ذات الأنظمة الإلكترونية المتعددة.</p>', 'Bosch S5 premium car battery 74Ah for reliable starts in all conditions.', 'بطارية سيارة بوش S5 المتميزة 74 أمبير لبدء تشغيل موثوق في جميع الظروف.', 'active', 0, 0, 0, 0, 0, NULL, 0, 0, 2, 236, 93543, NULL, 'Bosch S5 Car Battery 74Ah - noon', 'بطارية سيارة بوش S5 74 أمبير - نون', NULL, NULL, '2026-09-04 13:15:10', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-04-01 14:15:10', '2026-10-06 13:15:10', NULL, NULL, NULL),
('2049f581-fb67-445f-9a82-7d3d991f731d', '2997a13c-c3d1-4629-93df-5f50d10c9331', 'ee7e629c-321e-4adf-8dc9-14674231b115', 'Classic Slim Fit Oxford Shirt', 'قميص أوكسفورد ضيق الملاءمة الكلاسيكي', 'classic-slim-fit-oxford-shirt', NULL, NULL, '<p>Made from premium 100% cotton, this Oxford shirt features a button-down collar, chest pocket, and modern slim fit that flatters any build.</p>', '<p>مصنوع من القطن المميز 100%، يتميز هذا القميص بياقة أزرار وجيب صدر وقصة ضيقة عصرية.</p>', 'Crisp cotton Oxford shirt with a modern slim fit for everyday wear.', 'قميص أوكسفورد قطني أنيق بقصة ضيقة عصرية للارتداء اليومي.', 'active', 0, 0, 0, 0, 0, NULL, 0, 1, 3, 9996, 86642, NULL, 'Classic Slim Fit Oxford Shirt - noon', 'قميص أوكسفورد ضيق الملاءمة الكلاسيكي - نون', NULL, NULL, '2026-07-19 13:15:09', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-05-31 13:15:09', '2026-10-06 13:15:09', NULL, NULL, NULL),
('395935e7-5e70-431b-a720-132d1b2f9e3a', 'e6668d0c-4977-4b0b-a820-082b296c2c6a', 'fe0f26c6-f660-4641-8966-dbf911f7c876', 'iPhone 15 Pro', 'آيفون 15 برو', 'iphone-15-pro', 'A3290', NULL, '<p>The iPhone 15 Pro redefines smartphone excellence with its A17 Pro chip built on 3nm technology, a durable titanium frame, and a 48MP main camera system with ProRAW and ProRes video capabilities. Available in Natural Titanium, Blue Titanium, White Titanium, and Black Titanium.</p>', '<p>يعيد آيفون 15 برو تعريف التميز في الهواتف الذكية بشريحة A17 Pro المبنية على تقنية 3nm، وإطار تيتانيوم متين، ونظام كاميرا 48MP مع إمكانيات ProRAW وفيديو ProRes.</p>', 'Apple iPhone 15 Pro with A17 Pro chip, titanium design and ProRAW camera.', 'آيفون 15 برو بشريحة A17 Pro وتصميم تيتانيوم وكاميرا ProRAW.', 'active', 0, 0, 1, 0, 0, NULL, 0, 1, 2, 3634, 83836, NULL, 'iPhone 15 Pro - noon', 'آيفون 15 برو - نون', NULL, NULL, '2026-06-19 13:15:09', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-04-27 13:15:09', '2026-10-06 13:15:09', NULL, NULL, NULL),
('3e9fa83f-a7b5-436c-811c-e23b9eaa6886', '857381da-89ce-413b-8745-392ddff52030', '513fd519-7791-4503-85cf-90d9ef58ca1f', 'Adidas Ultraboost 23 Running Shoes', 'حذاء أديداس الترابوست 23 للجري', 'adidas-ultraboost-23', NULL, NULL, '<p>Every step in these running shoes returns energy to your stride with BOOST technology and a supportive Primeknit+ upper that adapts to your foot.</p>', '<p>كل خطوة في هذه الأحذية الجري تعيد الطاقة إلى خطاك مع تقنية BOOST وجزء علوي Primeknit+ داعم يتكيف مع قدمك.</p>', 'Adidas Ultraboost 23 with responsive BOOST midsole and Primeknit+ upper.', 'حذاء أديداس الترابوست 23 مع نعل BOOST الوسطي المتجاوب وجزء علوي Primeknit+.', 'active', 0, 0, 1, 0, 0, NULL, 0, 1, 2, 6748, 22027, NULL, 'Adidas Ultraboost 23 Running Shoes - noon', 'حذاء أديداس الترابوست 23 للجري - نون', NULL, NULL, '2026-09-14 13:15:10', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-02-05 14:15:10', '2026-10-06 13:15:10', NULL, NULL, NULL),
('4cd2fee7-eb32-4b1a-9c2d-7509303c7a36', '796fe5f9-5916-4c80-b201-163ae1d4f9ef', '04f2c1f1-f1fd-4ed3-8060-3773de133ddd', 'Vitamin D3 + K2 Supplement 5000 IU', 'مكمل فيتامين D3 + K2 5000 وحدة دولية', 'vitamin-d3-k2-5000iu', NULL, NULL, '<p>Each capsule provides 5000 IU of Vitamin D3 combined with 100mcg of K2 (MK-7 form) for optimal calcium absorption and cardiovascular health.</p>', '<p>كل كبسولة تحتوي على 5000 وحدة دولية من فيتامين D3 مع 100 ميكروغرام من K2.</p>', 'Premium Vitamin D3 with K2 for strong bones, immune support, and heart health.', 'فيتامين D3 مع K2 لتقوية العظام ودعم المناعة وصحة القلب.', 'active', 0, 0, 0, 0, 0, NULL, 0, 1, 3, 8598, 71331, NULL, 'Vitamin D3 + K2 Supplement 5000 IU - noon', 'مكمل فيتامين D3 + K2 5000 وحدة دولية - نون', NULL, NULL, '2026-05-13 13:15:10', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-01-24 14:15:10', '2026-10-06 13:15:10', NULL, NULL, NULL),
('6faf4630-0551-4652-89af-c1602ab9a830', 'f2f024df-f96b-4d22-aae5-a131011e4295', 'fe0f26c6-f660-4641-8966-dbf911f7c876', 'MacBook Pro 16\" M3 Max', 'ماك بوك برو 16 بوصة M3 ماكس', 'macbook-pro-16-m3-max', 'MRW13', NULL, '<p>MacBook Pro with M3 Max delivers exceptional performance for demanding workflows with up to 128GB unified memory.</p>', '<p>ماك بوك برو بشريحة M3 ماكس يقدم أداءً استثنائياً للعمليات المتطلبة مع ذاكرة موحدة تصل إلى 128 جيجابايت.</p>', 'The most powerful MacBook Pro ever with M3 Max chip, 16\" Liquid Retina XDR display.', 'أقوى ماك بوك برو على الإطلاق بشريحة M3 ماكس وشاشة Liquid Retina XDR 16 بوصة.', 'active', 0, 0, 1, 0, 0, NULL, 0, 1, 2, 7514, 15196, NULL, 'MacBook Pro 16\" M3 Max - noon', 'ماك بوك برو 16 بوصة M3 ماكس - نون', NULL, NULL, '2026-08-30 13:15:09', '150a1d19-b353-4bb1-b317-f943fde166a4', '2025-11-09 14:15:09', '2026-10-06 13:15:09', NULL, NULL, NULL),
('7eaee14c-daf6-4543-b8cf-3030af391e60', 'f2f024df-f96b-4d22-aae5-a131011e4295', '7f88b7e9-81fd-4684-9750-16267ede114e', 'Samsung Galaxy Book4 Pro 16\"', 'سامسونج جالاكسي بوك 4 برو 16 بوصة', 'samsung-galaxy-book4-pro-16', NULL, NULL, '<p>Ultra-thin and light laptop with Intel Core Ultra 7, 16GB LPDDR5 RAM, and Dynamic AMOLED 2X display.</p>', '<p>حاسوب محمول رفيع للغاية مع معالج إنتل كور الترا 7 وذاكرة LPDDR5 16 جيجابايت وشاشة Dynamic AMOLED 2X.</p>', 'Samsung Galaxy Book4 Pro with Intel Core Ultra 7, AMOLED display and AI features.', 'سامسونج جالاكسي بوك 4 برو مع معالج إنتل كور الترا 7 وشاشة AMOLED.', 'active', 0, 0, 0, 0, 0, NULL, 0, 0, 1, 966, 53903, NULL, 'Samsung Galaxy Book4 Pro 16\" - noon', 'سامسونج جالاكسي بوك 4 برو 16 بوصة - نون', NULL, NULL, '2026-09-01 13:15:09', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-09-06 13:15:09', '2026-10-06 13:15:09', NULL, NULL, NULL),
('80990096-47f8-46e6-a9b3-8218f37eb09f', 'e46b37e4-90a0-4754-9ec9-7762041d60f1', 'ba1346f6-f116-40fc-9cf9-4ed3a4b4146b', 'Nike Air Max 270', 'نايك اير ماكس 270', 'nike-air-max-270', NULL, NULL, '<p>The Nike Air Max 270 delivers lifestyle innovation with a full-length Air unit in the heel for incredible underfoot cushioning.</p>', '<p>توفر نايك اير ماكس 270 ابتكار أسلوب الحياة مع وحدة هواء كاملة الطول في الكعب لتوسيد لا مثيل له.</p>', 'Nike Air Max 270 with the biggest Air unit yet for all-day comfort.', 'نايك اير ماكس 270 بأكبر وحدة هواء حتى الآن لراحة طوال اليوم.', 'active', 0, 0, 1, 0, 0, NULL, 0, 1, 3, 3159, 1263, NULL, 'Nike Air Max 270 - noon', 'نايك اير ماكس 270 - نون', NULL, NULL, '2026-07-02 13:15:09', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-06-16 13:15:09', '2026-10-06 13:15:09', NULL, NULL, NULL),
('818b82f8-43fc-465f-811d-9d7e962b1d32', 'e4509a03-5a58-49bf-9e3f-6769058ec47a', 'eae05cfc-4eda-4f85-b5cf-5f5716c671bc', 'Philips Espresso Machine Series 3300', 'ماكينة إسبريسو فيليبس سلسلة 3300', 'philips-espresso-series-3300', NULL, NULL, '<p>The Philips Series 3300 fully automatic espresso machine features the unique LatteGo milk system and a wide range of specialty coffees.</p>', '<p>تتميز ماكينة فيليبس سلسلة 3300 بنظام LatteGo الفريد للحليب ومجموعة واسعة من قهوة التخصص.</p>', 'Fully automatic espresso machine with LatteGo milk system and intuitive touch display.', 'ماكينة إسبريسو أوتوماتيكية بالكامل مع نظام LatteGo للحليب وشاشة لمسية.', 'active', 0, 0, 0, 0, 0, NULL, 0, 0, 2, 4517, 71979, NULL, 'Philips Espresso Machine Series 3300 - noon', 'ماكينة إسبريسو فيليبس سلسلة 3300 - نون', NULL, NULL, '2026-09-17 13:15:10', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-08-07 13:15:10', '2026-10-06 13:15:10', NULL, NULL, NULL),
('98131d2e-bcc8-4735-803f-dedad96bd7c3', 'e6668d0c-4977-4b0b-a820-082b296c2c6a', '7f88b7e9-81fd-4684-9750-16267ede114e', 'Samsung Galaxy S24 Ultra', 'سامسونج جالاكسي S24 الترا', 'samsung-galaxy-s24-ultra', 'SM-S928B', NULL, '<p>The Galaxy S24 Ultra brings the ultimate Samsung experience with a 200MP camera, integrated S Pen, Snapdragon 8 Gen 3 processor, and 5000mAh battery.</p>', '<p>يجلب جالاكسي S24 الترا التجربة المثلى من سامسونج بكاميرا 200 ميجابكسل وقلم S Pen مدمج.</p>', 'Samsung Galaxy S24 Ultra with 200MP camera, built-in S Pen and Snapdragon 8 Gen 3.', 'سامسونج جالاكسي S24 الترا بكاميرا 200 ميجابكسل وقلم S Pen مدمج وسنابدراجون 8 الجيل الثالث.', 'active', 0, 0, 1, 0, 0, NULL, 0, 1, 2, 2396, 60129, NULL, 'Samsung Galaxy S24 Ultra - noon', 'سامسونج جالاكسي S24 الترا - نون', NULL, NULL, '2026-04-18 14:15:09', '150a1d19-b353-4bb1-b317-f943fde166a4', '2025-12-25 14:15:09', '2026-10-06 13:15:09', NULL, NULL, NULL),
('a5dcc9d2-c728-4ca7-9041-545dec96a698', '7341b036-109b-421a-8b0d-b478ab2091e2', '04f2c1f1-f1fd-4ed3-8060-3773de133ddd', 'LEGO Technic Bugatti Bolide Set', 'مجموعة ليغو تكنيك بوغاتي بوليد', 'lego-technic-bugatti-bolide', NULL, NULL, '<p>Build an incredible replica of the Bugatti Bolide hypercar with this LEGO Technic set, featuring 905 pieces including a distinctive W16 engine.</p>', '<p>ابنِ نسخة رائعة من سيارة بوغاتي بوليد الفائقة مع مجموعة ليغو تكنيك هذه، بـ 905 قطعة تشمل محرك W16 المميز.</p>', 'LEGO Technic Bugatti Bolide with 905 pieces for an authentic hypercar building experience.', 'مجموعة ليغو تكنيك بوغاتي بوليد بـ 905 قطعة لتجربة بناء سيارة فائقة السرعة أصيلة.', 'active', 0, 0, 0, 0, 0, NULL, 0, 0, 2, 8104, 33062, NULL, 'LEGO Technic Bugatti Bolide Set - noon', 'مجموعة ليغو تكنيك بوغاتي بوليد - نون', NULL, NULL, '2026-07-16 13:15:10', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-04-10 14:15:10', '2026-10-06 13:15:10', NULL, NULL, NULL),
('a7263425-49e0-41fc-852e-bbdf5d6ff107', '72da63d1-4b16-45c2-8bcc-bf153c73f712', 'a5862c8f-85f6-4223-a1ac-0615c786f276', 'Sony WH-1000XM5 Wireless Headphones', 'سماعات سوني WH-1000XM5 اللاسلكية', 'sony-wh-1000xm5', NULL, NULL, '<p>Sony WH-1000XM5 features industry-leading noise cancellation powered by two processors and eight microphones for an immersive listening experience.</p>', '<p>تتميز سماعات سوني WH-1000XM5 بإلغاء الضوضاء الرائد في الصناعة.</p>', 'Industry-leading noise canceling headphones with 30-hour battery life.', 'سماعات رائدة في صناعة إلغاء الضوضاء مع عمر بطارية 30 ساعة.', 'active', 0, 0, 0, 0, 0, NULL, 0, 1, 3, 2433, 47429, NULL, 'Sony WH-1000XM5 Wireless Headphones - noon', 'سماعات سوني WH-1000XM5 اللاسلكية - نون', NULL, NULL, '2026-06-28 13:15:09', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-08-30 13:15:09', '2026-10-06 13:15:09', NULL, NULL, NULL),
('a9f49313-5b93-4ee9-9334-a17e4523746b', 'fa4de438-4770-473e-ad2a-867b62c67d1c', '58defd22-47ac-435e-abe1-7204fd153fd0', 'Nivea Men\'s Energy Face Wash', 'غسول وجه نيفيا للرجال طاقة', 'nivea-mens-energy-face-wash', NULL, NULL, '<p>Start your day energized with Nivea Men Energy Face Wash. Formulated with mint extract to deeply cleanse and invigorate your skin.</p>', '<p>ابدأ يومك بنشاط مع غسول وجه نيفيا للرجال طاقة. مُصاغ بمستخلص النعناع لتنظيف بشرتك بعمق.</p>', 'Invigorating face wash for men with mint extract for a refreshed feeling.', 'غسول وجه منعش للرجال بمستخلص النعناع للشعور بالانتعاش.', 'active', 0, 0, 0, 0, 0, NULL, 0, 1, 3, 5282, 58376, NULL, 'Nivea Men\'s Energy Face Wash - noon', 'غسول وجه نيفيا للرجال طاقة - نون', NULL, NULL, '2026-06-19 13:15:10', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-03-08 14:15:10', '2026-10-06 13:15:10', NULL, NULL, NULL),
('c7aaad1f-7cfa-4999-94cf-af23a52bbf33', '8c638c79-9486-450e-9008-f0f69298a1ba', '4fba1ef3-ed85-47ce-8895-014eafeaa0fc', 'Dyson V15 Detect Absolute', 'دايسون V15 ديتكت أبسوليوت', 'dyson-v15-detect-absolute', NULL, NULL, '<p>The Dyson V15 Detect automatically adapts suction to the floor type. Its laser technology reveals microscopic dust invisible to the human eye.</p>', '<p>تتكيف مكنسة دايسون V15 ديتكت تلقائياً مع نوع الأرضية. تقنية الليزر الخاصة بها تكشف عن الغبار المجهري.</p>', 'Dyson V15 Detect cordless vacuum with laser technology to reveal invisible dust.', 'مكنسة دايسون V15 ديتكت اللاسلكية بتقنية الليزر للكشف عن الغبار غير المرئي.', 'active', 0, 0, 1, 0, 0, NULL, 0, 0, 2, 8454, 36562, NULL, 'Dyson V15 Detect Absolute - noon', 'دايسون V15 ديتكت أبسوليوت - نون', NULL, NULL, '2026-09-22 13:15:10', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-05-26 13:15:10', '2026-10-06 13:15:10', NULL, NULL, NULL),
('cf45d87b-2bc4-4129-9ac4-d674a19cac4b', 'aa0b0809-96f0-41ef-98bf-e9e25fcf553b', '0c47649b-6dc8-418e-ad49-f7bc52fe43c0', 'Women\'s Floral Maxi Dress', 'فستان ماكسي نسائي بنقشة زهور', 'womens-floral-maxi-dress', NULL, NULL, '<p>This beautiful floral maxi dress is crafted from lightweight, breathable fabric perfect for warm weather. Features a V-neck and adjustable straps.</p>', '<p>هذا الفستان الماكسي الجميل بنقشة الزهور مصنوع من قماش خفيف الوزن وقابل للتنفس مثالي للطقس الدافئ.</p>', 'Elegant floral maxi dress perfect for summer occasions.', 'فستان ماكسي أنيق بنقشة زهور مثالي لمناسبات الصيف.', 'active', 0, 0, 0, 0, 0, NULL, 0, 1, 3, 8773, 57429, NULL, 'Women\'s Floral Maxi Dress - noon', 'فستان ماكسي نسائي بنقشة زهور - نون', NULL, NULL, '2026-05-14 13:15:09', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-07-03 13:15:09', '2026-10-06 13:15:09', NULL, NULL, NULL),
('d054e492-e70e-4aa5-990f-ea91af4e0d9c', 'e6668d0c-4977-4b0b-a820-082b296c2c6a', 'a5f0a6cc-1218-43ef-96ce-34977bd16ae0', 'Xiaomi 14 Ultra', 'شاومي 14 الترا', 'xiaomi-14-ultra', 'Xiaomi 14 Ultra', NULL, '<p>Powered by Snapdragon 8 Gen 3 with Leica Summilux lenses and a 50MP main sensor.</p>', '<p>مدعوم بسنابدراجون 8 الجيل الثالث مع عدسات لايكا سوميلوكس.</p>', 'Xiaomi 14 Ultra with Leica Summilux optics and Snapdragon 8 Gen 3.', 'شاومي 14 الترا مع بصريات لايكا سوميلوكس وسنابدراجون 8 الجيل الثالث.', 'active', 0, 0, 0, 0, 0, NULL, 0, 1, 2, 6442, 67413, NULL, 'Xiaomi 14 Ultra - noon', 'شاومي 14 الترا - نون', NULL, NULL, '2026-06-08 13:15:09', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-06-04 13:15:09', '2026-10-06 13:15:09', NULL, NULL, NULL),
('d520bbd2-bf93-4d62-9d23-5641d8af71ab', 'e9dbbf71-8955-4a7a-b32e-d60056d0eefc', '04f2c1f1-f1fd-4ed3-8060-3773de133ddd', 'Nescafé Gold Blend Instant Coffee 200g', 'قهوة نسكافيه جولد بلند فورية 200 جم', 'nescafe-gold-blend-200g', NULL, NULL, '<p>Nescafé Gold Blend is a premium instant coffee made from a blend of Arabica and Robusta beans, expertly roasted for a rich, smooth taste.</p>', '<p>نسكافيه جولد بلند هي قهوة فورية ممتازة مصنوعة من مزيج حبوب أرابيكا وروبوستا.</p>', 'Nescafé Gold Blend rich instant coffee with a smooth, balanced taste.', 'قهوة نسكافيه جولد بلند الفورية الغنية بطعم ناعم ومتوازن.', 'active', 0, 0, 0, 0, 0, NULL, 0, 1, 3, 5766, 73309, NULL, 'Nescafé Gold Blend Instant Coffee 200g - noon', 'قهوة نسكافيه جولد بلند فورية 200 جم - نون', NULL, NULL, '2026-09-21 13:15:10', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-02-17 14:15:10', '2026-10-06 13:15:10', NULL, NULL, NULL),
('dea8283c-37c0-4a4b-8bec-c7604ddcc719', 'e4509a03-5a58-49bf-9e3f-6769058ec47a', 'fff1ce3d-8f3b-4ea4-89e8-b190fb3c913a', 'Tefal Easy Fry Air Fryer 4.2L', 'طاجن هواء تيفال إيزي فراي 4.2 لتر', 'tefal-easy-fry-air-fryer-4l', NULL, NULL, '<p>Cook healthier with the Tefal Easy Fry. Uses up to 99% less oil than traditional frying with its patented technology.</p>', '<p>اطبخ بشكل أكثر صحة مع تيفال إيزي فراي. تستخدم زيتاً أقل بنسبة 99% من القلي التقليدي.</p>', 'Tefal Easy Fry air fryer with 4.2L capacity for crispy results using up to 99% less oil.', 'قلاية هواء تيفال إيزي فراي بسعة 4.2 لتر لنتائج مقرمشة باستخدام زيت أقل بنسبة 99%.', 'active', 0, 0, 0, 0, 0, NULL, 0, 1, 3, 6165, 80063, NULL, 'Tefal Easy Fry Air Fryer 4.2L - noon', 'طاجن هواء تيفال إيزي فراي 4.2 لتر - نون', NULL, NULL, '2026-06-05 13:15:10', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-03-19 14:15:10', '2026-10-06 13:15:10', NULL, NULL, NULL),
('e8db57ca-0600-4631-af6a-b9b7f2daa213', '2997a13c-c3d1-4629-93df-5f50d10c9331', 'ee7e629c-321e-4adf-8dc9-14674231b115', 'Levi\'s 511 Slim Fit Jeans', 'جينز ليفايز 511 ضيق الملاءمة', 'levis-511-slim-fit-jeans', NULL, NULL, '<p>The 511 Slim Fit Jean sits just below the waist and fits through the thigh and knee with a leg opening that is narrower than our straight-fit jeans.</p>', '<p>جينز 511 بقصة ضيقة يجلس أسفل الخصر ويتميز بفتحة ساق أضيق من جينز القصة المستقيمة.</p>', 'Levi\'s 511 slim fit jeans in classic stretch denim.', 'جينز ليفايز 511 بقصة ضيقة من الدنيم المطاطي الكلاسيكي.', 'active', 0, 0, 0, 0, 0, NULL, 0, 1, 2, 2623, 58760, NULL, 'Levi\'s 511 Slim Fit Jeans - noon', 'جينز ليفايز 511 ضيق الملاءمة - نون', NULL, NULL, '2026-05-10 13:15:09', '150a1d19-b353-4bb1-b317-f943fde166a4', '2025-10-06 13:15:09', '2026-10-06 13:15:09', NULL, NULL, NULL),
('fc6cab46-c57d-4a32-8767-d921d1542070', 'fa4de438-4770-473e-ad2a-867b62c67d1c', '23587b1c-304a-435f-872c-6bdb945444d7', 'L\'Oréal Paris Revitalift Serum', 'سيروم لوريال باريس ريفيتاليفت', 'loreal-revitalift-serum', NULL, NULL, '<p>Revitalift 1.5% Pure Vitamin C Serum with Hyaluronic Acid visibly brightens and reduces wrinkles in just 1 week.</p>', '<p>سيروم ريفيتاليفت بتركيز 1.5% فيتامين C النقي مع حمض الهيالورونيك يضيء بشرتك بشكل ملحوظ ويقلل التجاعيد في أسبوع واحد فقط.</p>', 'Anti-aging serum with pure Vitamin C and Hyaluronic Acid for radiant skin.', 'سيروم مضاد للشيخوخة بفيتامين C النقي وحمض الهيالورونيك للبشرة المشرقة.', 'active', 0, 0, 0, 0, 0, NULL, 0, 0, 3, 7037, 12301, NULL, 'L\'Oréal Paris Revitalift Serum - noon', 'سيروم لوريال باريس ريفيتاليفت - نون', NULL, NULL, '2026-07-30 13:15:10', '150a1d19-b353-4bb1-b317-f943fde166a4', '2026-08-20 13:15:10', '2026-10-06 13:15:10', NULL, NULL, NULL);

